import{_ as a,o as t,c as o,a2 as l}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"Ceph Developer Monthly 2021-09-01","description":"","frontmatter":{"title":"Ceph Developer Monthly 2021-09-01","date":"2021-09-01T00:00:00.000Z","updated":"2021-09-03T00:00:00.000Z","tags":["Ceph配置文件","性能优化","EIO问题","大规模集群测试","资源受限环境"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2021/Ceph_Developer_Monthly_2021-09-01.md","filePath":"posts/2021/Ceph_Developer_Monthly_2021-09-01.md","lastUpdated":1780460162000}'),r={name:"posts/2021/Ceph_Developer_Monthly_2021-09-01.md"};function i(p,e,n,s,h,d){return t(),o("div",null,[...e[0]||(e[0]=[l('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议主题-ceph-配置文件与性能优化" tabindex="-1">会议主题：Ceph 配置文件与性能优化 <a class="header-anchor" href="#会议主题-ceph-配置文件与性能优化" aria-label="Permalink to &quot;会议主题：Ceph 配置文件与性能优化&quot;">​</a></h4><p><strong>讨论内容：</strong> 会议首先讨论了Ceph配置文件（Config Profiles）的引入，旨在解决资源受限环境中Ceph的部署问题。当前Ceph默认配置适用于高性能服务器，但越来越多的用户在资源受限的环境中部署Ceph，如家庭爱好集群、企业边缘部署等。会议提出了引入性能配置文件，如“边缘资源受限”和“高性能”配置文件，自动调整CPU和内存使用等参数的提议。</p><p><strong>决定事项：</strong></p><ul><li>初步确定至少两个配置文件：“边缘资源受限”和“高性能”。</li><li>配置文件将通过设置一个主配置选项来控制多个子配置参数，类似于Pacific中的服务质量配置文件。</li><li>需要进一步讨论和实验来确定具体的配置参数和默认值。</li></ul><h4 id="会议主题-处理无复制池的客户端eio问题" tabindex="-1">会议主题：处理无复制池的客户端EIO问题 <a class="header-anchor" href="#会议主题-处理无复制池的客户端eio问题" aria-label="Permalink to &quot;会议主题：处理无复制池的客户端EIO问题&quot;">​</a></h4><p><strong>讨论内容：</strong> 其次，会议讨论了无复制池的客户端EIO问题。在无复制池中，如果底层存储设备失败，客户端（如RBD）可能无法正确处理EIO错误，导致文件系统损坏。会议提出了引入池级别的EIO标志，一旦设置，客户端将立即返回EIO错误的提议。</p><p><strong>决定事项：</strong></p><ul><li>引入池级别的EIO标志，客户端检测到该标志后立即返回EIO错误。</li><li>需要确保客户端和服务端的一致性，特别是在多客户端环境下。</li><li>需要进一步讨论和实验来确定具体的实现细节。</li></ul><h4 id="会议主题-大规模集群测试" tabindex="-1">会议主题：大规模集群测试 <a class="header-anchor" href="#会议主题-大规模集群测试" aria-label="Permalink to &quot;会议主题：大规模集群测试&quot;">​</a></h4><p><strong>讨论内容：</strong> 最后，会议讨论了大规模集群测试的方法。为了测试Ceph在超大规模集群中的性能和稳定性，需要一种方法在不实际部署大量物理硬件的情况下进行测试。会议提出了使用内存 backed OSDs 和模拟数据存储来模拟大规模集群环境的提议。</p><p><strong>决定事项：</strong></p><ul><li>使用内存 backed OSDs 和模拟数据存储来模拟大规模集群环境。</li><li>需要进一步讨论和实验来确定具体的配置参数和模拟方法。</li></ul><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h3><p>本次会议主要讨论了Ceph在不同环境下的配置优化、无复制池的客户端EIO问题处理以及大规模集群测试的方法。决定引入性能配置文件、池级别的EIO标志和模拟数据存储来解决这些问题，并计划进行进一步的实验和社区讨论以完善这些方案。</p>',15)])])}const u=a(r,[["render",i]]);export{c as __pageData,u as default};
